{
 "command": "cd /tmp/mte-bf-notifier-sandbox-ygqsfmxt/ledgerline/services/notifier && for f in README.md pyproject.toml notifier/*.py; do echo \"=== $f\"; cat $f; done; grep -rn \"sink\\|MAIL_API\\|integration\\|markers\" -r . ../../Makefile ../../pyproject.toml ../../setup.cfg ../../pytest.ini 2>/dev/null | head -40",
 "description": "Show notifier sources and config"
}

{
 "command": "cd /tmp/mte-bf-notifier-sandbox-ygqsfmxt/ledgerline && cat Makefile pyproject.toml; grep -rni \"sink\\|inbox\" --exclude-dir=.git . | head; ls services/notifier/templates 2>&1",
 "description": "Check root config and search for sink API"
}

{
 "command": "env | grep -c \"MAIL_\" ; python -m pytest --import-mode=importlib tests -q -rs 2>&1 | tail -8",
